create table if not exists public.erp_qualidade_documentos_editor (id uuid primary key default gen_random_uuid(),empresa_id uuid not null,codigo_documento varchar(50) not null,titulo_documento varchar(255) not null,revisao integer not null default 1 check(revisao>0),data_homologacao date not null default current_date,conteudo_texto text not null default '',logo_path text,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),unique(empresa_id,codigo_documento));
create table if not exists public.erp_qualidade_documentos_revisoes (id uuid primary key default gen_random_uuid(),empresa_id uuid not null,codigo_documento varchar(50) not null,titulo_documento varchar(255) not null,departamento varchar(100) not null default 'QUALIDADE',revisao integer not null check(revisao>0),url_anexo varchar(500),nome_arquivo varchar(255),responsavel varchar(255) not null,status varchar(20) not null default 'VIGENTE' check(status in('VIGENTE','OBSOLETO')),assinatura_digital_hash varchar(64),conteudo_texto text not null default '',criado_em timestamptz not null default now(),unique(empresa_id,codigo_documento,revisao));
alter table public.erp_qualidade_documentos_editor enable row level security; alter table public.erp_qualidade_documentos_revisoes enable row level security;
drop policy if exists qualidade_editor_select on public.erp_qualidade_documentos_editor; drop policy if exists qualidade_editor_insert on public.erp_qualidade_documentos_editor; drop policy if exists qualidade_editor_update on public.erp_qualidade_documentos_editor; drop policy if exists qualidade_revisoes_select on public.erp_qualidade_documentos_revisoes; drop policy if exists qualidade_revisoes_insert on public.erp_qualidade_documentos_revisoes; drop policy if exists qualidade_revisoes_update on public.erp_qualidade_documentos_revisoes;
create policy qualidade_editor_select on public.erp_qualidade_documentos_editor for select to authenticated using(empresa_id=public.erp_current_empresa_id());
create policy qualidade_editor_insert on public.erp_qualidade_documentos_editor for insert to authenticated with check(empresa_id=public.erp_current_empresa_id());
create policy qualidade_editor_update on public.erp_qualidade_documentos_editor for update to authenticated using(empresa_id=public.erp_current_empresa_id()) with check(empresa_id=public.erp_current_empresa_id());
create policy qualidade_revisoes_select on public.erp_qualidade_documentos_revisoes for select to authenticated using(empresa_id=public.erp_current_empresa_id());
create policy qualidade_revisoes_insert on public.erp_qualidade_documentos_revisoes for insert to authenticated with check(empresa_id=public.erp_current_empresa_id());
create policy qualidade_revisoes_update on public.erp_qualidade_documentos_revisoes for update to authenticated using(empresa_id=public.erp_current_empresa_id()) with check(empresa_id=public.erp_current_empresa_id());
insert into storage.buckets(id,name,public) values('erp-documentos-qualidade','erp-documentos-qualidade',false) on conflict(id) do update set public=false;
drop policy if exists qualidade_storage_select on storage.objects; drop policy if exists qualidade_storage_insert on storage.objects;
create policy qualidade_storage_select on storage.objects for select to authenticated using(bucket_id='erp-documentos-qualidade');
create policy qualidade_storage_insert on storage.objects for insert to authenticated with check(bucket_id='erp-documentos-qualidade');
create or replace function public.erp_salvar_revisao_documento(p_codigo text,p_titulo text,p_departamento text,p_conteudo text,p_logo_path text default null,p_url_anexo text default null,p_nome_arquivo text default null) returns jsonb language plpgsql security invoker as $$
declare v_empresa uuid:=public.erp_current_empresa_id();v_old integer;v_new integer;v_id uuid;
begin if v_empresa is null then raise exception 'Empresa não identificada';end if;if trim(coalesce(p_codigo,''))='' or trim(coalesce(p_titulo,''))='' then raise exception 'Código e título são obrigatórios';end if;
select revisao into v_old from public.erp_qualidade_documentos_editor where empresa_id=v_empresa and codigo_documento=trim(p_codigo) for update;v_new:=coalesce(v_old,0)+1;
update public.erp_qualidade_documentos_revisoes set status='OBSOLETO' where empresa_id=v_empresa and codigo_documento=trim(p_codigo) and status='VIGENTE';
insert into public.erp_qualidade_documentos_revisoes(empresa_id,codigo_documento,titulo_documento,departamento,revisao,url_anexo,nome_arquivo,responsavel,status,conteudo_texto) values(v_empresa,trim(p_codigo),trim(p_titulo),coalesce(nullif(trim(p_departamento),''),'QUALIDADE'),v_new,p_url_anexo,p_nome_arquivo,coalesce((select coalesce(nome,email) from public.erp_usuarios where auth_user_id=auth.uid() and empresa_id=v_empresa limit 1),(select email from auth.users where id=auth.uid()),'USUARIO'),'VIGENTE',coalesce(p_conteudo,'')) returning id into v_id;
insert into public.erp_qualidade_documentos_editor(empresa_id,codigo_documento,titulo_documento,revisao,data_homologacao,conteudo_texto,logo_path,atualizado_em) values(v_empresa,trim(p_codigo),trim(p_titulo),v_new,current_date,coalesce(p_conteudo,''),p_logo_path,now()) on conflict(empresa_id,codigo_documento) do update set titulo_documento=excluded.titulo_documento,revisao=excluded.revisao,data_homologacao=excluded.data_homologacao,conteudo_texto=excluded.conteudo_texto,logo_path=excluded.logo_path,atualizado_em=now();
return jsonb_build_object('id',v_id,'revisao',v_new,'data_homologacao',current_date);end;$$;
revoke all on function public.erp_salvar_revisao_documento(text,text,text,text,text,text,text) from public;grant execute on function public.erp_salvar_revisao_documento(text,text,text,text,text,text,text) to authenticated;
create or replace function public.erp_proteger_assinatura_revisao() returns trigger language plpgsql as $$ begin if old.assinatura_digital_hash is not null and (new.assinatura_digital_hash is distinct from old.assinatura_digital_hash or new.status is distinct from old.status or new.conteudo_texto is distinct from old.conteudo_texto or new.titulo_documento is distinct from old.titulo_documento) then raise exception 'Revisão assinada é imutável';end if;return new;end;$$;
drop trigger if exists trg_erp_proteger_assinatura_revisao on public.erp_qualidade_documentos_revisoes;create trigger trg_erp_proteger_assinatura_revisao before update on public.erp_qualidade_documentos_revisoes for each row execute function public.erp_proteger_assinatura_revisao();